import os, json, ssl
import urllib.request
import urllib.error

cs_url = os.environ.get('CS_API_URL', '').strip()
cs_token = os.environ.get('CS_API_TOKEN', '').strip()

# The shipped .env carries REPLACE_WITH_* placeholders. Treat those as "not
# configured" so a stack that never wired up Cobalt Strike does not attempt a
# doomed connection on every 5-minute tick.
def _placeholder(v):
    return v.upper().startswith('REPLACE_WITH')

if not cs_url or _placeholder(cs_url):
    return [{'json': {'fetch_ok': False, 'configured': False,
                      'error': 'CS_API_URL is not set (or still the .env placeholder)',
                      'beacons': []}}]
if _placeholder(cs_token):
    return [{'json': {'fetch_ok': False, 'configured': False,
                      'error': 'CS_API_TOKEN is still the .env placeholder',
                      'beacons': []}}]

ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE

headers = {}
if cs_token:
    if cs_token.lower().startswith(('token ', 'bearer ')):
        headers['Authorization'] = cs_token
    else:
        headers['Authorization'] = f'Token {cs_token}'

try:
    req = urllib.request.Request(
        cs_url.rstrip('/') + '/beacons',
        headers=headers,
        method='GET',
    )
    with urllib.request.urlopen(req, timeout=15, context=ctx) as r:
        payload = json.loads(r.read())

    if isinstance(payload, dict):
        beacons = payload.get('beacons')
        if beacons is None:
            beacons = payload.get('data')
        if beacons is None:
            beacons = [payload]
    elif isinstance(payload, list):
        beacons = payload
    else:
        beacons = []

    return [{'json': {'fetch_ok': True, 'error': '', 'beacons': beacons}}]
except urllib.error.HTTPError as e:
    body = ''
    try:
        body = e.read().decode('utf-8', errors='replace')[:300]
    except Exception:
        body = ''
    return [{'json': {'fetch_ok': False, 'error': f'CS API HTTP {e.code}: {body}', 'beacons': []}}]
except Exception as e:
    return [{'json': {'fetch_ok': False, 'error': f'CS API request failed: {e}', 'beacons': []}}]
